    enum On {
        PreTick(Run),
        Tick(Run),
        Toggle(Toggled),
        Out(Sent),
        In(Seen),
        Key(Keyed),
        Hud(Painted),
        World(Painted),
        Join(Run),
        Leave(Left),
        Hurt(Hurt),
        Death(Run),
        Chat(Said),
        Stop(Stopped),
    }
    const KINDS: usize = 14;
    impl On {
        fn kind(&self) -> usize {
            match self {
                On::PreTick(_) => 0,
                On::Tick(_) => 1,
                On::Toggle(_) => 2,
                On::Out(_) => 3,
                On::In(_) => 4,
                On::Key(_) => 5,
                On::Hud(_) => 6,
                On::World(_) => 7,
                On::Join(_) => 8,
                On::Leave(_) => 9,
                On::Hurt(_) => 10,
                On::Death(_) => 11,
                On::Chat(_) => 12,
                On::Stop(_) => 13,
            }
        }
    }
