    fn plain_name(name: &str) -> bool {
        !name.is_empty() && name.len() <= 32
            && name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-')
    }
    #[allow(dead_code)]
    pub(super) fn plugin(
        game: &mut Game<'_>,
        id: &'static str,
        version: &'static str,
        setup: impl FnOnce(&mut Plugin),
    ) {
        if !RUNTIME.running() || !game.native_window() {
            return;
        }
        {
            let mut plugins = lock(&PLUGINS);
            if plugins.iter().any(|p| p.id == id) {
                return;
            }
            plugins
                .push(Loaded {
                    id,
                    version,
                    modules: Vec::new(),
                    commands: Vec::new(),
                    failed: None,
                });
        }
        if !plain_name(id) || id == super::sunset::ID {
            let why = format!(
                "its id \"{id}\" can't be used: use your mod's id, lower case letters, digits, - and _ (not \"sunset\")"
            );
            if let Some(p) = lock(&PLUGINS).iter_mut().find(|p| p.id == id) {
                p.failed = Some(why.clone());
            }
            note(format!("Plugin {id} is off: {why}."));
            return;
        }
        let mut p = Plugin { id, priority: NORMAL };
        guarded(id, "setup", || setup(&mut p));
        super::sunset::finish_shutdown(game);
    }
