pub(crate) mod sunset_movement {
    pub(super) fn steer(
        current: [f64; 2],
        direction: Option<[f64; 2]>,
        target_speed: f64,
        acceleration: f64,
        deceleration: f64,
        strafe_strength: f64,
        limit: f64,
    ) -> [f64; 2] {
        if !current.iter().all(|v| v.is_finite()) || !target_speed.is_finite()
            || !limit.is_finite()
        {
            return [0.0, 0.0];
        }
        let limit = limit.clamp(0.0, 2.0);
        let current_len = current[0].hypot(current[1]);
        let current = if current_len > limit && current_len > 0.0 {
            [current[0] * limit / current_len, current[1] * limit / current_len]
        } else {
            current
        };
        let Some(direction) = direction.filter(|d| d.iter().all(|v| v.is_finite())) else {
            let deceleration = if deceleration.is_finite() {
                deceleration.clamp(0.0, 2.0)
            } else {
                0.0
            };
            let keep = if current_len > 0.0 {
                (current_len - deceleration).max(0.0) / current_len
            } else {
                0.0
            };
            return [current[0] * keep, current[1] * keep];
        };
        let dir_len = direction[0].hypot(direction[1]);
        if dir_len <= 1e-12 {
            return current;
        }
        let target = target_speed.clamp(0.0, limit);
        let desired = [direction[0] / dir_len * target, direction[1] / dir_len * target];
        let turn = if strafe_strength.is_finite() {
            strafe_strength.clamp(0.0, 1.0)
        } else {
            0.0
        };
        let aimed = [
            current[0] + (desired[0] - current[0]) * turn,
            current[1] + (desired[1] - current[1]) * turn,
        ];
        let delta = [aimed[0] - current[0], aimed[1] - current[1]];
        let delta_len = delta[0].hypot(delta[1]);
        let accel = if acceleration.is_finite() {
            acceleration.clamp(0.0, 2.0)
        } else {
            0.0
        };
        let fraction = if delta_len > accel && delta_len > 0.0 {
            accel / delta_len
        } else {
            1.0
        };
        let next = [current[0] + delta[0] * fraction, current[1] + delta[1] * fraction];
        let len = next[0].hypot(next[1]);
        if len > limit && len > 0.0 {
            [next[0] * limit / len, next[1] * limit / len]
        } else {
            next
        }
    }
    pub(super) fn velocity_factor(scale_percent: f64, blend_percent: f64) -> f64 {
        if !scale_percent.is_finite() || !blend_percent.is_finite() {
            return 1.0;
        }
        let scale = scale_percent.clamp(0.0, 100.0) / 100.0;
        let blend = blend_percent.clamp(0.0, 100.0) / 100.0;
        1.0 + (scale - 1.0) * blend
    }
    pub(super) fn item_use_factor(
        using_item: bool,
        no_slow_percent: Option<[f64; 2]>,
        on_ground: bool,
    ) -> f64 {
        if !using_item {
            return 1.0;
        }
        let Some(percent) = no_slow_percent.map(|v| if on_ground { v[0] } else { v[1] })
        else {
            return 1.0;
        };
        if percent.is_finite() { percent.clamp(20.0, 100.0) / 100.0 } else { 1.0 }
    }
    pub(super) fn legacy_use_factor(
        no_slow_percent: Option<[f64; 2]>,
        on_ground: bool,
    ) -> f32 {
        item_use_factor(true, Some(no_slow_percent.unwrap_or([20.0; 2])), on_ground)
            as f32
    }
    pub(super) fn turn_toward(from: f32, to: f32, max_degrees: f32) -> f32 {
        if !from.is_finite() || !to.is_finite() || !max_degrees.is_finite() {
            return from;
        }
        let delta = (to - from + 180.0).rem_euclid(360.0) - 180.0;
        from + delta.clamp(-max_degrees.max(0.0), max_degrees.max(0.0))
    }
    pub(super) fn speed_can_write(
        flight: bool,
        fall_flying: bool,
        using_item: bool,
        no_slow: bool,
        knockback_ticks: u32,
        wall: bool,
        stop_at_wall: bool,
    ) -> bool {
        !flight && !fall_flying && (!using_item || no_slow) && knockback_ticks == 0
            && (!wall || !stop_at_wall)
    }
    #[cfg(test)]
    mod tests {
        use super::*;
        #[test]
        fn translated_blocking_keeps_normal_slowdown_and_existing_no_slow_percentages() {
            assert_eq!(legacy_use_factor(None, true), 0.2);
            assert_eq!(legacy_use_factor(Some([50.0, 80.0]), true), 0.5);
            assert_eq!(legacy_use_factor(Some([50.0, 80.0]), false), 0.8);
            assert_eq!(legacy_use_factor(Some([100.0; 2]), false), 1.0);
        }
        #[test]
        fn steering_accelerates_and_caps_without_diagonal_gain() {
            let v = steer([0.0, 0.0], Some([1.0, 1.0]), 0.4, 0.1, 0.1, 1.0, 0.4);
            assert!((v[0].hypot(v[1]) - 0.1).abs() < 1e-10);
            let v = steer([10.0, 0.0], Some([1.0, 0.0]), 0.4, 0.1, 0.1, 1.0, 0.4);
            assert!(v[0].hypot(v[1]) <= 0.4 + 1e-10);
        }
        #[test]
        fn steering_decelerates_and_handles_invalid_state() {
            assert!(
                (steer([0.3, 0.0], None, 0.4, 0.1, 0.1, 1.0, 0.5) [0] - 0.2).abs() <
                1e-10
            );
            assert_eq!(
                steer([f64::NAN, 1.0], Some([f64::INFINITY, 0.0]), 0.4, 0.1, 0.1, 1.0,
                0.5), [0.0, 0.0]
            );
        }
        #[test]
        fn velocity_blend_keeps_a_bounded_share_of_server_motion() {
            assert_eq!(velocity_factor(0.0, 100.0), 0.0);
            assert_eq!(velocity_factor(0.0, 50.0), 0.5);
            assert_eq!(velocity_factor(100.0, 100.0), 1.0);
            assert_eq!(velocity_factor(f64::NAN, 100.0), 1.0);
        }
        #[test]
        fn rotation_uses_shortest_wrapped_turn() {
            assert!((turn_toward(179.0, - 179.0, 1.0) - 180.0).abs() < 1e-5);
            assert_eq!(turn_toward(0.0, 90.0, 20.0), 20.0);
        }
        #[test]
        fn speed_yields_to_flight_item_use_knockback_and_walls() {
            assert!(speed_can_write(false, false, false, false, 0, false, true));
            assert!(! speed_can_write(true, false, false, false, 0, false, true));
            assert!(! speed_can_write(false, false, true, false, 0, false, true));
            assert!(! speed_can_write(false, false, false, false, 2, false, true));
            assert!(! speed_can_write(false, false, false, false, 0, true, true));
            assert!(speed_can_write(false, false, true, true, 0, false, true));
        }
        #[test]
        fn item_use_factor_preserves_configured_ground_and_air_slowdown() {
            assert_eq!(item_use_factor(true, Some([50.0, 80.0]), true), 0.5);
            assert_eq!(item_use_factor(true, Some([50.0, 80.0]), false), 0.8);
            assert_eq!(item_use_factor(false, Some([50.0, 80.0]), true), 1.0);
            assert_eq!(item_use_factor(true, None, true), 1.0);
        }
    }
}
pub(crate) mod sunset_murder {
    use super::sunset::{Module, Shape};
    use super::{Dim, Game};
    use std::collections::VecDeque;
    use std::sync::Mutex;
    use std::time::{Duration, Instant};
    #[derive(Default)]
    struct Finder {
        world: Option<(i32, Dim)>,
        suspects: Vec<(u32, String)>,
        pending: VecDeque<String>,
        sent: Option<Instant>,
    }
    static FINDER: Mutex<Option<Finder>> = Mutex::new(None);
    fn finder<R>(f: impl FnOnce(&mut Finder) -> R) -> R {
        f(
            FINDER
                .lock()
                .unwrap_or_else(|e| e.into_inner())
                .get_or_insert_with(Finder::default),
        )
    }
    fn listed(game: &Game<'_>, list: &str, item: &str) -> bool {
        let short = super::sunset_util::short(item);
        list.split(',')
            .map(str::trim)
            .filter(|e| !e.is_empty())
            .any(|e| {
                let e = super::sunset_util::short(e);
                e == short
                    || game
                        .res
                        .items()
                        .item_tags
                        .get(&format!("minecraft:{e}"))
                        .is_some_and(|items| items.contains(item))
            })
    }
    fn callout(m: &Module, name: &str, tick: u64) -> Option<String> {
        let messages: Vec<&str> = m
            .t("Callout messages")
            .split(';')
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .collect();
        let pick = messages
            .get(
                (tick.wrapping_mul(0x9E37_79B9) % messages.len().max(1) as u64) as usize,
            )?;
        Some(pick.replace("%s", name))
    }
    pub(super) fn tick(game: &mut Game<'_>, esp: Option<&Module>) {
        let Some(m) = esp.filter(|m| m.b("Murderer finder")) else {
            finder(|f| *f = Finder::default());
            return;
        };
        let world = game.remote.as_ref().map(|r| (r.entity_id, game.dim));
        let own = game.remote.as_ref().map(|r| r.entity_id);
        finder(|f| {
            if f.world != world {
                *f = Finder {
                    world,
                    ..Finder::default()
                };
            }
        });
        if world.is_none() {
            return;
        }
        let delay = Duration::from_millis(m.n("Callout delay (ms)").max(0.0) as u64);
        if let Some(line) = finder(|f| {
                (!f.pending.is_empty() && f.sent.is_none_or(|t| t.elapsed() >= delay))
                    .then(|| {
                        f.sent = Some(Instant::now());
                        f.pending.pop_front()
                    })
            })
            .flatten()
        {
            game.send_chat(&line);
        }
        let names = game.remote_player_names();
        let found: Vec<(u32, String)> = game
            .mobs
            .iter()
            .filter(|mob| {
                mob.kind.id == "minecraft:player" && mob.alive() && !mob.removed
                    && Some(mob.id as i32) != own
            })
            .filter(|mob| {
                mob
                    .extra
                    .main_hand
                    .as_deref()
                    .is_some_and(|item| listed(game, m.t("Murderer items"), item))
            })
            .filter(|mob| finder(|f| f.suspects.iter().all(|s| s.0 != mob.id)))
            .map(|mob| (
                mob.id,
                names
                    .iter()
                    .find(|n| n.0 == mob.id)
                    .map_or_else(|| format!("#{}", mob.id), |n| n.1.clone()),
            ))
            .collect();
        for (id, name) in found {
            let line = m.b("Callout").then(|| callout(m, &name, game.ticks)).flatten();
            finder(|f| {
                f.suspects.push((id, name));
                f.pending.extend(line);
            });
        }
    }
    pub(super) fn suspect(id: u32) -> bool {
        finder(|f| f.suspects.iter().any(|s| s.0 == id))
    }
    pub(super) fn draw(game: &Game<'_>, esp: &Module, w: f32, out: &mut Vec<Shape>) {
        if !esp.b("Murderer finder") || !esp.b("Murderer list") {
            return;
        }
        let here: Vec<String> = finder(|f| {
            f.suspects
                .iter()
                .filter(|s| game.mobs.iter().any(|m| m.id == s.0 && !m.removed))
                .map(|s| s.1.clone())
                .collect()
        });
        if here.is_empty() {
            return;
        }
        let colour = esp.c("Murderer color") & 0xFF_FFFF;
        let title = "Murderer list";
        out.push(
            Shape::Text(
                title.to_owned(),
                [(w - game.native_text_width(title)) / 2.0, 15.0],
                0xFFFFFF,
            ),
        );
        for (row, name) in here.into_iter().enumerate() {
            out.push(
                Shape::Text(
                    name.clone(),
                    [
                        (w - game.native_text_width(&name)) / 2.0,
                        26.0 + row as f32 * 10.0,
                    ],
                    colour,
                ),
            );
        }
    }
    #[cfg(test)]
    mod tests {
        use super::*;
        #[test]
        fn a_callout_names_the_player_in_one_of_the_messages() {
            let m = Module::new("ESP", super::super::sunset::Category::Render, "")
                .text("Callout messages", "%s is the murderer!; i saw that %s!");
            let said: std::collections::BTreeSet<String> = (0..64)
                .filter_map(|t| callout(&m, "Alex", t))
                .collect();
            assert_eq!(
                said.into_iter().collect::< Vec < _ >> (), ["Alex is the murderer!",
                "i saw that Alex!"]
            );
            let none = Module::new("ESP", super::super::sunset::Category::Render, "")
                .text("Callout messages", " ; ");
            assert_eq!(callout(& none, "Alex", 3), None);
        }
    }
}
pub(crate) mod sunset_new_chunks {
    use super::sunset::{Camera, Canvas, Category, Module};
    use super::sunset_util::*;
    use super::Game;
    use horizon_protocol::chunk::{Section, storage_get};
    use horizon_world::registry::BlockStateId;
    use std::collections::HashMap;
    use std::io::Write;
    use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
    use std::sync::mpsc::{Receiver, Sender, channel};
    use std::sync::Mutex;
    pub(super) fn defaults() -> Vec<Module> {
        vec![
            Module::new("New Chunks", Category::World, "Shows new and old chunks.")
            .bool("Palette method", true).bool("Liquid method", true).bool("Save", true)
            .bool("Show old", true).num("Render distance", 32.0, 4.0, 128.0, 4.0)
            .num("Render height", 0.0, - 64.0, 320.0, 1.0).colour("New color", "Red")
            .colour("Old color", "Green").num("Fill opacity", 0.25, 0.0, 1.0, 0.05),
            Module::new("Player Activity Detector", Category::World,
            "Finds chunks players keep loaded.").num("Recent visit (s)", 60.0, 0.0,
            600.0, 5.0).bool("Chat", true).colour("Color", "Purple"),
        ]
    }
    const NEW: u8 = 1;
    const OLD: u8 = 2;
    static ON: AtomicBool = AtomicBool::new(false);
    static NOW: AtomicU64 = AtomicU64::new(0);
    static RECENT: AtomicU64 = AtomicU64::new(0);
    struct Arrival {
        chunk: (i32, i32),
        buffer: Vec<u8>,
        sections: usize,
        biome_bits: u8,
        stale: bool,
    }
    struct Verdict {
        chunk: (i32, i32),
        palette: u8,
        flowing: bool,
        stale: u32,
    }
    #[derive(Default)]
    struct Nc {
        key: String,
        file: Option<std::fs::File>,
        chunks: HashMap<(i32, i32), u8>,
        jobs: Option<Sender<Arrival>>,
        verdicts: Option<Receiver<Verdict>>,
        flows: Vec<(i32, i32)>,
        had: HashMap<(i32, i32), u64>,
        active: Vec<(i32, i32)>,
    }
    static NC: Mutex<Option<Nc>> = Mutex::new(None);
    fn nc<R>(f: impl FnOnce(&mut Nc) -> R) -> R {
        f(NC.lock().unwrap_or_else(|e| e.into_inner()).get_or_insert_with(Nc::default))
    }
    pub(crate) fn arrived(
        x: i32,
        z: i32,
        buffer: &[u8],
        sections: usize,
        biome_bits: u8,
    ) {
        if !ON.load(Ordering::Relaxed) {
            return;
        }
        let (now, recent) = (
            NOW.load(Ordering::Relaxed),
            RECENT.load(Ordering::Relaxed),
        );
        nc(|n| {
            let stale = n
                .had
                .get(&(x, z))
                .is_none_or(|&t| now.saturating_sub(t) > recent);
            if let Some(jobs) = &n.jobs {
                let _ = jobs
                    .send(Arrival {
                        chunk: (x, z),
                        buffer: buffer.to_vec(),
                        sections,
                        biome_bits,
                        stale,
                    });
            }
        });
    }
    pub(super) fn block_update(game: &Game<'_>, pos: [i32; 3], state: i32) {
        if !ON.load(Ordering::Relaxed) || state < 0 {
            return;
        }
        let facts = game.res.facts();
        let s = facts.get(BlockStateId(state as u32));
        if s.fluid_level == 0 || (s.fluid_level == 8 && !s.fluid_falling) {
            return;
        }
        let source = [[1, 0, 0], [-1, 0, 0], [0, 1, 0], [0, 0, 1], [0, 0, -1]]
            .iter()
            .any(|d| {
                let n = facts
                    .get(game.world.block(pos[0] + d[0], pos[1] + d[1], pos[2] + d[2]));
                n.fluid_level == 8 && !n.fluid_falling
            });
        if source {
            nc(|n| n.flows.push((pos[0] >> 4, pos[2] >> 4)));
        }
    }
    fn judge(a: &Arrival, air: u32, flowing: &[bool]) -> Option<Verdict> {
        let mut r = horizon_protocol::buf::Reader::new(&a.buffer);
        let sections: Vec<Section> = (0..a.sections)
            .map(|_| Section::read(&mut r, 16, a.biome_bits))
            .collect::<Result<_, _>>()
            .ok()?;
        let (mut new, mut old, mut stale, mut flows) = (0u32, 0u32, 0u32, false);
        let is_flowing = |id: i32| {
            usize::try_from(id)
                .ok()
                .and_then(|i| flowing.get(i))
                .copied()
                .unwrap_or(false)
        };
        for s in &sections {
            let p = &s.states;
            if p.bits == 0 {
                flows |= p.palette.first().is_some_and(|&id| is_flowing(id));
                continue;
            }
            if p.palette.is_empty() {
                flows
                    |= (0..4096)
                        .any(|i| is_flowing(storage_get(&p.data, p.bits, i) as i32));
                continue;
            }
            flows |= p.palette.iter().any(|&id| is_flowing(id));
            let first = p
                .palette
                .get(storage_get(&p.data, p.bits, 0) as usize)
                .copied()
                .unwrap_or(0);
            if p.palette[0] == air as i32 && first != air as i32 {
                new += 1;
            } else if p.palette[0] != air as i32 {
                old += 1;
            }
            if a.stale {
                let mut used = vec![false; p.palette.len()];
                for i in 0..4096 {
                    if let Some(u) = used
                        .get_mut(storage_get(&p.data, p.bits, i) as usize)
                    {
                        *u = true;
                    }
                }
                stale += u32::from(used.contains(&false));
            }
        }
        let palette = match (new, old) {
            (0, 0) => 0,
            (n, o) if n >= o => NEW,
            _ => OLD,
        };
        Some(Verdict {
            chunk: a.chunk,
            palette,
            flowing: flows,
            stale,
        })
    }
    fn path(game: &Game<'_>) -> Option<std::path::PathBuf> {
        let dim = short(game.dim.id()).replace(['/', ':'], "_");
        Some(
            game
                .native_data_dir(super::sunset::ID)
                .join("newchunks")
                .join(format!("{:016x}-{dim}.txt", world_hash(game) ?)),
        )
    }
    fn load(path: &std::path::Path) -> HashMap<(i32, i32), u8> {
        let text = std::fs::read_to_string(path).unwrap_or_default();
        text.lines()
            .filter_map(|l| {
                let mut w = l.split_whitespace();
                let (x, z) = (w.next()?.parse().ok()?, w.next()?.parse().ok()?);
                let v = match w.next()? {
                    "n" => NEW,
                    "o" => OLD,
                    _ => return None,
                };
                Some(((x, z), v))
            })
            .collect()
    }
    pub(super) fn tick(game: &mut Game<'_>, mods: &[Module]) {
        let get = |n: &str| mods.iter().find(|m| m.name == n && m.on);
        let (chunks, activity) = (get("New Chunks"), get("Player Activity Detector"));
        let on = (chunks.is_some() || activity.is_some()) && game.remote.is_some();
        ON.store(on, Ordering::Relaxed);
        NOW.store(game.ticks, Ordering::Relaxed);
        RECENT
            .store(
                activity.map_or(0, |m| (m.n("Recent visit (s)") * 20.0) as u64),
                Ordering::Relaxed,
            );
        if !on {
            nc(|n| *n = Nc::default());
            return;
        }
        let save = chunks.is_some_and(|m| m.b("Save"));
        let file = path(game).filter(|_| save);
        let key = format!("{}|{}|{save}", world_hash(game).unwrap_or(0), game.dim.id());
        if nc(|n| n.key != key) {
            let loaded = file.as_deref().map(load).unwrap_or_default();
            let opened = file
                .and_then(|p| {
                    std::fs::create_dir_all(p.parent()?).ok()?;
                    std::fs::OpenOptions::new().create(true).append(true).open(p).ok()
                });
            let facts = game.res.facts();
            let air = facts
                .states
                .iter()
                .position(|s| short(&s.name) == "air")
                .unwrap_or(0) as u32;
            let flowing: Vec<bool> = facts
                .states
                .iter()
                .map(|s| s.fluid_level > 0 && (s.fluid_level < 8 || s.fluid_falling))
                .collect();
            let (jobs, rx) = channel::<Arrival>();
            let (tx, verdicts) = channel();
            let generation = horizon_protocol::connection::sunset_lifecycle::RUNTIME
                .token();
            let thread = move || {
                for a in rx {
                    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME
                        .current(generation)
                    {
                        return;
                    }
                    let verdict = judge(&a, air, &flowing);
                    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME
                        .current(generation)
                    {
                        return;
                    }
                    if let Some(v) = verdict && tx.send(v).is_err() {
                        return;
                    }
                }
            };
            let started = std::thread::Builder::new()
                .name("sunset-new-chunks".into())
                .spawn(thread)
                .is_ok();
            nc(|n| {
                *n = Nc {
                    key,
                    file: opened,
                    chunks: loaded,
                    ..Nc::default()
                };
                if started {
                    n.jobs = Some(jobs);
                    n.verdicts = Some(verdicts);
                }
            });
        }
        if game.ticks % 20 == 0 {
            let now = game.ticks;
            nc(|n| {
                for (c, _) in game.world.chunks.iter() {
                    n.had.insert(*c, now);
                }
            });
        }
        let horizon = game
            .remote
            .as_ref()
            .is_some_and(|r| r.brand.to_ascii_lowercase().contains("horizon"));
        let (palette, liquid) = chunks
            .map_or(
                (true, false),
                |m| (m.b("Palette method") && !horizon, m.b("Liquid method")),
            );
        let found = nc(|n| {
            let verdicts: Vec<Verdict> = n
                .verdicts
                .as_ref()
                .map(|r| r.try_iter().collect())
                .unwrap_or_default();
            let mut decided = Vec::new();
            let mut active = Vec::new();
            for v in verdicts {
                let verdict = if palette && v.palette != 0 {
                    v.palette
                } else if liquid && v.flowing && !horizon {
                    OLD
                } else {
                    0
                };
                if verdict != 0 && !n.chunks.contains_key(&v.chunk) {
                    decided.push((v.chunk, verdict));
                }
                if !horizon && v.palette == OLD && v.stale > 0
                    && !n.active.contains(&v.chunk)
                {
                    active.push((v.chunk, v.stale));
                }
            }
            for c in std::mem::take(&mut n.flows) {
                if liquid && !n.chunks.contains_key(&c)
                    && !decided.iter().any(|d| d.0 == c)
                {
                    decided.push((c, NEW));
                }
            }
            for &(c, v) in &decided {
                n.chunks.insert(c, v);
                if let Some(f) = n.file.as_mut() {
                    let _ = writeln!(
                        f, "{} {} {}", c.0, c.1, if v == NEW { "n" } else { "o" }
                    );
                }
            }
            if activity.is_none() {
                active.clear();
            }
            n.active.extend(active.iter().map(|a| a.0));
            active
        });
        if activity.is_some_and(|m| m.b("Chat")) {
            for ((x, z), stale) in found {
                let s = if stale == 1 { "" } else { "s" };
                report(
                    game,
                    &format!(
                        "Player activity? chunk {x} {z} ({} {}): {stale} section{s} changed since it loaded",
                        x * 16 + 8, z * 16 + 8
                    ),
                );
            }
        }
    }
    pub(super) fn draw(cam: &Camera, mods: &[Module], out: &mut impl Canvas) {
        let get = |n: &str| mods.iter().find(|m| m.name == n && m.on);
        let (chunks, activity) = (get("New Chunks"), get("Player Activity Detector"));
        if chunks.is_none() && activity.is_none() {
            return;
        }
        let eye = cam.eye();
        let (cx, cz) = ((eye[0].floor() as i32) >> 4, (eye[2].floor() as i32) >> 4);
        nc(|n| {
            if let Some(m) = chunks {
                let r = m.n("Render distance") as i32;
                let alpha = |argb: u32| {
                    ((((argb >> 24) as f64 * m.n("Fill opacity")).round() as u32) << 24)
                        | (argb & 0x00FF_FFFF)
                };
                let (new, old) = (alpha(m.c("New color")), alpha(m.c("Old color")));
                let y = m.n("Render height");
                for x in cx - r..=cx + r {
                    for z in cz - r..=cz + r {
                        let argb = match n.chunks.get(&(x, z)) {
                            Some(&NEW) => new,
                            Some(_) if m.b("Show old") => old,
                            _ => continue,
                        };
                        square(cam, out, x, z, y, argb);
                    }
                }
            }
            if let Some(m) = activity {
                let argb = (m.c("Color") & 0x00FF_FFFF) | 0x6000_0000;
                for &(x, z) in &n.active {
                    square(cam, out, x, z, eye[1] - 2.0, argb);
                }
            }
        });
    }
    fn square(cam: &Camera, out: &mut impl Canvas, x: i32, z: i32, y: f64, argb: u32) {
        let (x0, z0) = (f64::from(x * 16), f64::from(z * 16));
        if !cam.sees([x0 + 8.0, y, z0 + 8.0], 12.0) {
            return;
        }
        let part = |x0: f64, z0: f64, s: f64| {
            let c = [[x0, y, z0], [x0 + s, y, z0], [x0 + s, y, z0 + s], [x0, y, z0 + s]]
                .map(|p| cam.project(p));
            match c {
                [Some(a), Some(b), Some(c), Some(d)] => Some([a, b, c, d]),
                _ => None,
            }
        };
        if let Some(q) = part(x0, z0, 16.0) {
            out.quad(q, argb);
            return;
        }
        for i in 0..4 {
            for j in 0..4 {
                if let Some(q) = part(
                    x0 + f64::from(i) * 4.0,
                    z0 + f64::from(j) * 4.0,
                    4.0,
                ) {
                    out.quad(q, argb);
                }
            }
        }
    }
    #[cfg(test)]
    mod tests {
        use super::*;
        use horizon_protocol::chunk::Paletted;
        fn section(palette: Vec<i32>, values: &[u32]) -> Section {
            let mut data = vec![0i64; 4096 / 16];
            for (i, &v) in values.iter().enumerate() {
                data[i / 16] |= (i64::from(v)) << ((i % 16) * 4);
            }
            Section {
                non_empty: 4096,
                fluids: 0,
                states: Paletted { bits: 4, palette, data },
                biomes: Paletted {
                    bits: 0,
                    palette: vec![0],
                    data: vec![],
                },
            }
        }
        fn judged(sections: &[Section]) -> Verdict {
            let buffer = horizon_protocol::chunk::ChunkData::from_sections(sections);
            judge(
                    &Arrival {
                        chunk: (0, 0),
                        buffer,
                        sections: sections.len(),
                        biome_bits: 6,
                        stale: true,
                    },
                    0,
                    &[false, false, false, false],
                )
                .unwrap()
        }
        #[test]
        fn a_palette_that_starts_with_air_under_stone_is_new() {
            let mut values = vec![1u32; 4096];
            values[4095] = 0;
            let v = judged(&[section(vec![0, 1], &values)]);
            assert_eq!(v.palette, NEW);
            let packed: Vec<u32> = values.iter().map(|&b| 1 - b).collect();
            let v = judged(&[section(vec![1, 0], &packed)]);
            assert_eq!((v.palette, v.stale), (OLD, 0));
            let v = judged(&[section(vec![1, 0, 3], &packed)]);
            assert_eq!((v.palette, v.stale), (OLD, 1));
        }
    }
}
pub(crate) mod sunset_ore_sim {
    use super::{Dim, Game};
    use super::sunset::{Camera, Canvas, Category, Module};
    use super::sunset_util::{dist, player_pos, toggle_off};
    use super::sunset_visual::{Look, draw_box};
    use horizon_client::chunk::{Chunk, MIN_Y};
    use horizon_world::registry::{BlockRegistry, BlockStateId};
    use horizon_world::worldgen::generator::sunset_ore_sim::{KINDS, SeenWorld, ore_sim};
    use std::collections::{HashMap, HashSet};
    use std::path::PathBuf;
    use std::sync::mpsc::{Receiver, Sender, channel};
    use std::sync::{Arc, Mutex};
    pub(super) const NAME: &str = "Ore Sim";
    const TOP: i32 = 320;
    const SEND_PER_TICK: usize = 6;
    pub(super) fn defaults() -> Vec<Module> {
        vec![
            Module::new(NAME, Category::World, "Shows ores from the world seed.")
            .text("Seed", "").num("Chunks", 5.0, 1.0, 10.0, 1.0).text("Ores",
            "coal,copper,iron,lapis,redstone,gold,diamond,emerald,quartz,debris")
            .bool("Hide shown ores", false).num("Max", 4096.0, 64.0, 16384.0, 64.0),
        ]
    }
    const COLOURS: [u32; 10] = [
        0xFF34_3434, 0xFFE0_7A4F, 0xFFD8_AF93, 0xFF1E_4ED8, 0xFFFF_2020, 0xFFFF_D700,
        0xFF4F_E8E0, 0xFF17_DD62, 0xFFEE_E6DC, 0xFF8A_5A44,
    ];
    struct Job {
        at: (i32, i32),
        chunks: Vec<Arc<Chunk>>,
    }
    enum Done {
        Chunk((i32, i32), Vec<([i32; 3], u8)>),
        Failed(String),
    }
    struct Sim {
        key: (i64, &'static str),
        jobs: Sender<Job>,
        done: Receiver<Done>,
        sent: HashSet<(i32, i32)>,
        ores: HashMap<(i32, i32), Vec<([i32; 3], u8)>>,
        ore_states: Vec<bool>,
        said: bool,
    }
    static SIM: Mutex<Option<Sim>> = Mutex::new(None);
    fn seed(text: &str) -> Option<i64> {
        let text = text.trim();
        if text.is_empty() {
            return None;
        }
        Some(
            text
                .parse::<i64>()
                .unwrap_or_else(|_| {
                    i64::from(
                        text
                            .encode_utf16()
                            .fold(
                                0i32,
                                |h, c| h.wrapping_mul(31).wrapping_add(i32::from(c)),
                            ),
                    )
                }),
        )
    }
    fn dimension(game: &Game<'_>) -> (&'static str, (i32, i32), (i32, i32, i32)) {
        match game.dim {
            Dim::Overworld => ("minecraft:overworld", (-64, 384), (-64, 384, 63)),
            Dim::Nether => ("minecraft:the_nether", (0, 256), (0, 128, 32)),
            Dim::End => ("minecraft:the_end", (0, 256), (0, 128, 0)),
        }
    }
    fn floor_blocks(game: &Game<'_>) -> Vec<bool> {
        const LATER: [&str; 10] = [
            "_log",
            "_wood",
            "_stem",
            "_hyphae",
            "mushroom_block",
            "bee_nest",
            "pumpkin",
            "melon",
            "cactus",
            "bamboo",
        ];
        game.res
            .facts()
            .states
            .iter()
            .map(|s| {
                s.full_collision && !s.classes.iter().any(|c| &**c == "LeavesBlock")
                    && !LATER.iter().any(|w| s.name.contains(w))
            })
            .collect()
    }
    fn ore_states(registry: &BlockRegistry) -> Vec<bool> {
        (0..registry.len() as u32)
            .map(|id| {
                registry
                    .state(BlockStateId(id))
                    .is_some_and(|s| {
                        s.name.ends_with("_ore") || s.name == "minecraft:ancient_debris"
                    })
            })
            .collect()
    }
    impl Sim {
        fn start(
            game: &Game<'_>,
            key: (i64, &'static str),
            build: (i32, i32),
            generation: (i32, i32, i32),
        ) -> Option<Self> {
            let lifecycle = horizon_protocol::connection::sunset_lifecycle::RUNTIME
                .token();
            let registry: &'static BlockRegistry = game.pack.assets.registry;
            let dir: PathBuf = game.options.resources.join("worldgen");
            let biome_names: Vec<String> = game
                .res
                .biomes()
                .list
                .iter()
                .map(|b| b.name.clone())
                .collect();
            let solid = floor_blocks(game);
            let (jobs, rx) = channel::<Job>();
            let (tx, done) = channel();
            let thread = move || {
                if !horizon_protocol::connection::sunset_lifecycle::RUNTIME
                    .current(lifecycle)
                {
                    return;
                }
                let loaded = horizon_client::vanillagen::shared_data(&dir, registry)
                    .map_err(|e| e.to_string())
                    .and_then(|data| ore_sim(
                        &data,
                        "minecraft:normal",
                        key.1,
                        build,
                        generation,
                    ));
                let sim = match loaded {
                    Ok(Some(sim)) if sim.roots() > 0 => sim,
                    Ok(_) => {
                        let _ = tx
                            .send(
                                Done::Failed("no ores generate in this dimension".into()),
                            );
                        return;
                    }
                    Err(e) => {
                        let _ = tx
                            .send(
                                Done::Failed(
                                    format!("the world generator would not load ({e})"),
                                ),
                            );
                        return;
                    }
                };
                let biomes: Vec<Option<u32>> = biome_names
                    .iter()
                    .map(|n| sim.biome_index(n))
                    .collect();
                let air = registry.default_state("minecraft:air").map_or(0, |s| s.0);
                for job in rx {
                    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME
                        .current(lifecycle)
                    {
                        return;
                    }
                    let view = View {
                        at: job.at,
                        chunks: &job.chunks,
                        biomes: &biomes,
                        solid: &solid,
                        air,
                    };
                    let found = sim.chunk(key.0, job.at.0, job.at.1, &view);
                    if !horizon_protocol::connection::sunset_lifecycle::RUNTIME
                        .current(lifecycle)
                    {
                        return;
                    }
                    if tx.send(Done::Chunk(job.at, found)).is_err() {
                        return;
                    }
                }
            };
            std::thread::Builder::new()
                .name("sunset-ore-sim".into())
                .spawn(thread)
                .ok()?;
            Some(Self {
                key,
                jobs,
                done,
                sent: HashSet::new(),
                ores: HashMap::new(),
                ore_states: ore_states(registry),
                said: false,
            })
        }
    }
    struct View<'a> {
        at: (i32, i32),
        chunks: &'a [Arc<Chunk>],
        biomes: &'a [Option<u32>],
        solid: &'a [bool],
        air: u32,
    }
    impl View<'_> {
        fn chunk(&self, x: i32, z: i32) -> Option<&Chunk> {
            let (dx, dz) = ((x >> 4) - self.at.0 + 1, (z >> 4) - self.at.1 + 1);
            ((0..3).contains(&dx) && (0..3).contains(&dz))
                .then(|| &*self.chunks[(dz * 3 + dx) as usize])
        }
    }
    impl SeenWorld for View<'_> {
        fn block(&self, p: [i32; 3]) -> Option<BlockStateId> {
            let chunk = self.chunk(p[0], p[2])?;
            Some(
                BlockStateId(
                    if (MIN_Y..TOP).contains(&p[1]) {
                        chunk.get(p[0], p[1], p[2])
                    } else {
                        self.air
                    },
                ),
            )
        }
        fn biome(&self, p: [i32; 3]) -> Option<u32> {
            let chunk = self.chunk(p[0], p[2])?;
            *self.biomes.get(usize::from(chunk.biome(p[0], p[1], p[2])))?
        }
        fn floor(&self, x: i32, z: i32) -> Option<i32> {
            let chunk = self.chunk(x, z)?;
            let top = chunk
                .highest(
                    self.air,
                    |y| {
                        self
                            .solid
                            .get(chunk.get(x, y, z) as usize)
                            .copied()
                            .unwrap_or(false)
                    },
                );
            Some(top.map_or(MIN_Y, |y| y + 1))
        }
        fn biomes_near(&self) -> Vec<u32> {
            let mut found = HashSet::new();
            for chunk in self.chunks {
                let (x0, z0) = (chunk.x * 16, chunk.z * 16);
                for y in (MIN_Y..TOP).step_by(4) {
                    for q in 0..16 {
                        let biome = chunk.biome(x0 + (q & 3) * 4, y, z0 + (q >> 2) * 4);
                        if let Some(Some(b)) = self.biomes.get(usize::from(biome)) {
                            found.insert(*b);
                        }
                    }
                }
            }
            found.into_iter().collect()
        }
    }
    pub(super) fn tick(game: &mut Game<'_>, mods: &[Module]) {
        let Some(m) = mods.iter().find(|m| m.name == NAME && m.on) else {
            *SIM.lock().unwrap_or_else(|e| e.into_inner()) = None;
            return;
        };
        let Some(seed) = seed(m.t("Seed")) else {
            super::sunset::say(
                game,
                "Ore Sim: set the world's seed first (.set oresim seed <seed>).",
            );
            toggle_off(game, NAME);
            return;
        };
        let Some(here) = player_pos(game) else { return };
        let (dim, build, generation) = dimension(game);
        let key = (seed, dim);
        let mut slot = SIM.lock().unwrap_or_else(|e| e.into_inner());
        if slot.as_ref().is_none_or(|s| s.key != key) {
            *slot = Sim::start(game, key, build, generation);
        }
        let Some(sim) = slot.as_mut() else { return };
        let mut failed = None;
        for done in sim.done.try_iter() {
            match done {
                Done::Chunk(at, found) => {
                    sim.ores.insert(at, found);
                }
                Done::Failed(why) => failed = Some(why),
            }
        }
        if let Some(why) = failed {
            drop(slot);
            super::sunset::say(game, &format!("Ore Sim: {why}."));
            toggle_off(game, NAME);
            return;
        }
        let r = m.n("Chunks") as i32;
        let (cx, cz) = ((here[0].floor() as i32) >> 4, (here[2].floor() as i32) >> 4);
        let chunks = &game.world.chunks;
        let near = |c: &(i32, i32)| {
            (c.0 - cx).abs() <= r + 1 && (c.1 - cz).abs() <= r + 1
                && chunks.contains_key(c)
        };
        sim.sent.retain(near);
        sim.ores.retain(|c, _| near(c));
        let mut sent = 0;
        let mut waiting = false;
        for dz in -r..=r {
            for dx in -r..=r {
                let at = (cx + dx, cz + dz);
                if sim.sent.contains(&at) {
                    continue;
                }
                let around: Option<Vec<Arc<Chunk>>> = (-1..=1)
                    .flat_map(|j| (-1..=1).map(move |i| (at.0 + i, at.1 + j)))
                    .map(|c| chunks.get(&c).cloned())
                    .collect();
                let Some(around) = around else { continue };
                waiting = true;
                if sent < SEND_PER_TICK
                    && sim.jobs.send(Job { at, chunks: around }).is_ok()
                {
                    sim.sent.insert(at);
                    sent += 1;
                }
            }
        }
        if sim.said || waiting || sim.ores.is_empty() || sim.ores.len() < sim.sent.len()
        {
            return;
        }
        sim.said = true;
        let found: usize = sim.ores.values().map(Vec::len).sum();
        let shown = sim
            .ores
            .values()
            .flatten()
            .filter(|(p, _)| {
                sim
                    .ore_states
                    .get(game.world.block(p[0], p[1], p[2]).0 as usize)
                    .copied()
                    .unwrap_or(false)
            })
            .count();
        let line = format!(
            "Ore Sim: {found} ores in {} chunks, {shown} of them already show as ore.",
            sim.ores.len()
        );
        drop(slot);
        super::sunset::say(game, &line);
    }
    pub(super) fn draw(
        game: &Game<'_>,
        cam: &Camera,
        mods: &[Module],
        out: &mut impl Canvas,
        lw: f32,
    ) {
        let Some(m) = mods.iter().find(|m| m.name == NAME && m.on) else { return };
        let Some(here) = player_pos(game) else { return };
        let wanted: Vec<bool> = KINDS
            .iter()
            .map(|k| m.t("Ores").split(',').any(|o| o.trim() == *k))
            .collect();
        let (hide_shown, max) = (m.b("Hide shown ores"), m.n("Max") as usize);
        let range = (m.n("Chunks") * 16.0 + 16.0) * 1.5;
        let slot = SIM.lock().unwrap_or_else(|e| e.into_inner());
        let Some(sim) = slot.as_ref() else { return };
        let mut drawn = 0;
        for &(p, kind) in sim.ores.values().flatten() {
            if !wanted[kind as usize] {
                continue;
            }
            let lo = [f64::from(p[0]), f64::from(p[1]), f64::from(p[2])];
            if dist(here, [lo[0] + 0.5, lo[1] + 0.5, lo[2] + 0.5]) > range {
                continue;
            }
            let state = game.world.block(p[0], p[1], p[2]);
            if game.world.is_air(state)
                || (hide_shown
                    && sim.ore_states.get(state.0 as usize).copied().unwrap_or(false))
            {
                continue;
            }
            if draw_box(
                cam,
                out,
                &Look::BOXED,
                lo,
                [lo[0] + 1.0, lo[1] + 1.0, lo[2] + 1.0],
                COLOURS[kind as usize],
                lw,
            ) {
                drawn += 1;
                if drawn >= max {
                    break;
                }
            }
        }
    }
}
pub(crate) mod sunset_packet_mine {
    use super::sunset::{Category, Module, hold, with};
    use super::sunset_util::{center_of, dist, sequence, show, turned_to};
    use super::Game;
    use horizon_protocol::packets::Empty;
    use horizon_protocol::packets::play::{self, Serverbound as S};
    use std::sync::Mutex;
    const NAME: &str = "Packet Mine";
    pub(super) fn defaults() -> Vec<Module> {
        vec![
            Module::new(NAME, Category::World, "Mines blocks in the background.")
            .num("Delay (ticks)", 1.0, 0.0, 10.0, 1.0).bool("Rotate", true)
            .bool("Best tool", true).bool("Not on use", true).bool("Render", true)
            .num("Queue", 8.0, 1.0, 32.0, 1.0),
        ]
    }
    #[derive(Clone, Copy)]
    struct Block {
        pos: [i32; 3],
        direction: u8,
        state: horizon_world::registry::BlockStateId,
        wait: u32,
        done: Option<f32>,
        stopped: Option<u64>,
    }
    #[derive(Default)]
    struct State {
        queue: Vec<Block>,
        back: Option<usize>,
    }
    static STATE: Mutex<Option<State>> = Mutex::new(None);
    fn st<R>(f: impl FnOnce(&mut State) -> R) -> R {
        let mut s = STATE.lock().unwrap_or_else(|e| e.into_inner());
        f(s.get_or_insert_with(State::default))
    }
    fn module() -> Option<Module> {
        with(|s| s.module(NAME).filter(|m| m.on).cloned())
    }
    pub(super) fn click(game: &mut Game<'_>, swing: bool) -> bool {
        let Some(m) = module() else {
            return false;
        };
        if game.creative || game.remote.is_none() || game.entity_targeted() {
            return false;
        }
        let Some(hit) = game.pick() else {
            return false;
        };
        let state = game.world.block(hit.pos[0], hit.pos[1], hit.pos[2]);
        let facts = game.res.facts().get(state);
        if facts.hardness < 0.0 || game.res.facts().is_air(state) {
            return false;
        }
        let direction = horizon_core::geometry::Direction::ALL
            .iter()
            .position(|d| d.normal() == hit.face)
            .unwrap_or(1) as u8;
        st(|s| {
            if !s.queue.iter().any(|b| b.pos == hit.pos)
                && s.queue.len() < m.n("Queue") as usize
            {
                s.queue
                    .push(Block {
                        pos: hit.pos,
                        direction,
                        state,
                        wait: m.n("Delay (ticks)") as u32,
                        done: None,
                        stopped: None,
                    });
            }
        });
        if swing {
            game.swing_arm();
            game.send(S::Punch(Empty));
        }
        true
    }
    fn progress_with(game: &mut Game<'_>, slot: usize, pos: [i32; 3]) -> f32 {
        let held = game.selected;
        game.selected = slot;
        let step = game.destroy_progress(pos);
        game.selected = held;
        step
    }
    fn best_slot(game: &mut Game<'_>, m: &Module, pos: [i32; 3]) -> usize {
        if !m.b("Best tool") || (m.b("Not on use") && game.using.is_some()) {
            return game.selected;
        }
        (0..9)
            .fold(
                game.selected,
                |best, i| {
                    if progress_with(game, i, pos) > progress_with(game, best, pos) {
                        i
                    } else {
                        best
                    }
                },
            )
    }
    pub(super) fn tick(game: &mut Game<'_>) {
        if let Some(slot) = st(|s| s.back.take()) {
            hold(game, slot);
        }
        let Some(m) = module() else {
            st(|s| s.queue.clear());
            return;
        };
        let Some(eye) = game.eye_position() else {
            return;
        };
        let ticks = game.ticks;
        let reach = game.reach() + 1.0;
        st(|s| {
            s.queue
                .retain(|b| {
                    game.world.block(b.pos[0], b.pos[1], b.pos[2]) == b.state
                        && dist(eye, center_of(b.pos)) <= reach
                        && b.stopped.is_none_or(|t| ticks < t + 20)
                })
        });
        if m.b("Render") {
            for b in st(|s| s.queue.clone()) {
                let p = b.done.map_or(0.0, |d| (d / 0.7).min(1.0));
                let (r, g) = ((255.0 * (1.0 - p)) as u32, (255.0 * p) as u32);
                show(b.pos, 0x6000_0000 | r << 16 | g << 8);
            }
        }
        let Some(mut b) = st(|s| s.queue.first().copied()) else {
            return;
        };
        if b.stopped.is_some() {
            return;
        }
        let rotate = m.b("Rotate");
        match b.done {
            None if b.wait > 0 => b.wait -= 1,
            None => {
                b.done = Some(0.0);
                let (pos, direction) = (b.pos, b.direction);
                turned_to(
                    game,
                    NAME,
                    rotate,
                    center_of(pos),
                    move |game| {
                        let sequence = sequence(game);
                        game.send(
                            S::PlayerAction(play::PlayerAction {
                                action: 0,
                                pos,
                                direction,
                                sequence,
                            }),
                        );
                        game.swing_arm();
                    },
                );
            }
            Some(done) => {
                let slot = best_slot(game, &m, b.pos);
                let done = done + progress_with(game, slot, b.pos);
                b.done = Some(done);
                if done >= 0.7 {
                    b.stopped = Some(ticks);
                    let (pos, direction) = (b.pos, b.direction);
                    turned_to(
                        game,
                        NAME,
                        rotate,
                        center_of(pos),
                        move |game| {
                            let before = game.selected;
                            hold(game, slot);
                            let sequence = sequence(game);
                            game.send(
                                S::PlayerAction(play::PlayerAction {
                                    action: 3,
                                    pos,
                                    direction,
                                    sequence,
                                }),
                            );
                            if slot != before {
                                st(|s| s.back = Some(before));
                            }
                        },
                    );
                }
            }
        }
        st(|s| {
            if let Some(first) = s.queue.first_mut().filter(|f| f.pos == b.pos) {
                *first = b;
            }
        });
    }
    pub(super) fn toggled(game: &mut Game<'_>, name: &str, on: bool) {
        if name != NAME || on {
            return;
        }
        let digging = st(|s| std::mem::take(&mut s.queue))
            .into_iter()
            .find(|b| b.done.is_some() && b.stopped.is_none());
        if let Some(b) = digging {
            game.send(
                S::PlayerAction(play::PlayerAction {
                    action: 2,
                    pos: b.pos,
                    direction: b.direction,
                    sequence: 0,
                }),
            );
        }
    }
}
