            let Some((slot, ticks)) = using.filter(|_| eligible) else {
                *self = Self::default();
                return false;
            };
            let continued = self
                .last_use
                .is_some_and(|(last_slot, last_ticks)| {
                    last_slot == slot && last_ticks.checked_add(1) == Some(ticks)
                });
