    pub(super) const CRIT_FALL: u8 = 5;
    pub(super) const CRIT_LAND: u8 = 6;
    pub(super) static CRIT_HOP: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(
        0,
    );
    pub(super) static CRIT_JUMP: AtomicBool = AtomicBool::new(false);
    pub(super) static CRIT_SPRINT: std::sync::atomic::AtomicU8 = std::sync::atomic::AtomicU8::new(
        0,
    );
