            assert_eq!(turned_keys(1, 0, 0.0, 10.0), (1, 0));
            assert_eq!(turned_keys(1, 0, 0.0, 30.0), (1, 1));
            assert_eq!(turned_keys(1, 0, 0.0, 22.5), (1, 0));
